const input = $input.first().json || {};
const body = input.body ?? {};
const dados = body.dados ?? {};
const conteudo = (dados.conteudo ?? '').toString().trim();
const aba = (body.aba ?? '').toString().trim();
const campo = (dados.campo ?? '').toString().trim();
const errors = [];
if (!aba) errors.push('Campo obrigatório ausente: body.aba');
if (!campo) errors.push('Campo obrigatório ausente: body.dados.campo');
if (!conteudo) errors.push('Campo obrigatório ausente: body.dados.conteudo');
return { ...input, body: { ...body, dados: { ...dados, conteudo, campo, estado_atual: dados.estado_atual ?? { dados_gerais: {} } } }, prompt_key: campo, _validation: { isValid: errors.length === 0, errors } };

const input = $input.first().json || {};
const aba = (input.body?.aba ?? '').toString().trim();
const campo = (input.body?.dados?.campo ?? '').toString().trim();
const validationErrors = input._validation?.errors ?? [];
let code = 'ROUTING_ERROR';
let message = 'Não foi possível rotear a requisição no workflow.';
if (validationErrors.length > 0) { code = 'VALIDATION_ERROR'; message = 'Payload inválido. Corrija os campos obrigatórios e tente novamente.'; } else if (aba && aba !== 'dados_gerais') { code = 'UNSUPPORTED_ABA'; message = `Aba não suportada: ${aba}. Valor esperado: dados_gerais.`; } else if (campo) { code = 'UNSUPPORTED_CAMPO'; message = `Campo não suportado: ${campo}.`; }
return { campo: campo || null, conteudo: message, erro: { code, message, details: validationErrors }, debug: { aba: aba || null, campo: campo || null } };

const input = $input.first().json || {};
const key = `prompt:${input.prompt_key}:active`;
const cache = this.getWorkflowStaticData('global');
const item = cache[key];
const ttlMs = 15 * 60 * 1000;
const valid = item && item.updated_at && (Date.now() - new Date(item.updated_at).getTime() < ttlMs);
if (!valid) return { ...input, cache_hit: false, cache_key: key };
return { ...input, cache_hit: true, cache_key: key, prompt_template: item.prompt_template, prompt_version: item.prompt_version ?? 1, prompt_source: 'cache' };

const input = $input.first().json || {};
if (input.erro?.code) return input;
const conteudo = (input.body?.dados?.conteudo ?? '').toString();
const dadosGerais = input.body?.dados?.estado_atual?.dados_gerais ?? {};
const template = (input.prompt_template ?? '').toString();
if (!template) return { ...input, erro: { code: 'PROMPT_NOT_FOUND', message: `Prompt não encontrado para o campo: ${input.prompt_key}` } };
const renderedPrompt = template.replaceAll('{{ JSON.stringify($json.body.dados.estado_atual.dados_gerais) }}', JSON.stringify(dadosGerais)).replaceAll('{ JSON.stringify($json.body.dados.estado_atual.dados_gerais) }', JSON.stringify(dadosGerais)).replaceAll('{{ $json.body.dados.conteudo }}', conteudo).replaceAll('{ $json.body.dados.conteudo }', conteudo);
return { ...input, prompt_base: renderedPrompt };

const input = $input.first().json || {};
const rawResponse = input.response;
const normalizeParsed = (parsed) => { if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return { campo: parsed.campo ?? input.body?.dados?.campo ?? null, conteudo: (parsed.conteudo ?? '').toString().trim() || JSON.stringify(parsed), erro: parsed.erro ?? null, debug: { ...(parsed.debug ?? {}), prompt_version: input.prompt_version ?? null, cache_hit: input.cache_hit ?? false, rag_hit_count: input.rag_hit_count ?? 0 } }; return { campo: input.body?.dados?.campo ?? null, conteudo: (parsed ?? '').toString().trim(), erro: null, debug: { prompt_version: input.prompt_version ?? null, cache_hit: input.cache_hit ?? false, rag_hit_count: input.rag_hit_count ?? 0 } }; };
try { if (rawResponse === undefined || rawResponse === null) throw new Error('A resposta da IA veio vazia'); if (typeof rawResponse === 'object') return normalizeParsed(rawResponse); const cleanData = rawResponse.toString().replace(/```json|```/gi, '').replace(/<[^>]*>/g, '').trim(); if (!cleanData) throw new Error('A resposta da IA veio vazia após limpeza'); try { return normalizeParsed(JSON.parse(cleanData)); } catch { return normalizeParsed(cleanData); } } catch (e) { return { campo: input.body?.dados?.campo ?? null, conteudo: 'Falha ao processar resposta da IA.', erro: { code: 'PARSE_ERROR', message: e.message }, debug: { prompt_version: input.prompt_version ?? null, cache_hit: input.cache_hit ?? false, rag_hit_count: input.rag_hit_count ?? 0 } }; }

const previous = $('IF Cache Hit').first().json;
const response = $input.first().json;
const row = Array.isArray(response) ? response[0] : (response?.data?.[0] ?? response?.[0] ?? response);
if (!row?.prompt_template) return { ...previous, erro: { code: 'PROMPT_NOT_FOUND', message: `Prompt não encontrado para o campo: ${previous.prompt_key}` }, debug: { prompt_key: previous.prompt_key, source: 'supabase' } };
const cache = this.getWorkflowStaticData('global');
cache[previous.cache_key] = { prompt_template: row.prompt_template, prompt_version: row.versao ?? 1, updated_at: new Date().toISOString() };
return { ...previous, prompt_template: row.prompt_template, prompt_version: row.versao ?? 1, prompt_source: 'supabase', cache_hit: false };

const base = $('Anexar Embedding').first().json;
if (base.erro?.code) return base;
const vectorResp = $input.first().json;
const docs = vectorResp?.documents ?? vectorResp?.data ?? [];
const ragContext = Array.isArray(docs) ? docs.map((d, i) => { const source = d?.source ?? `doc_${i+1}`; const text = (d?.text ?? '').toString().trim(); return text ? `• [${source}] ${text}` : ''; }).filter(Boolean).join('\n') : '';
const finalPrompt = ragContext ? `${base.prompt_base}\n\n## Contexto RAG\n${ragContext}` : base.prompt_base;
return { ...base, prompt: finalPrompt, rag_context: ragContext, rag_hit_count: Array.isArray(docs) ? docs.length : 0 };
